int read_multimedia_header(AVFormatContext *avctx) {
    int version;

    // Skip initial bytes
    if (avio_skip(avctx->pb, 12) < 0)
        return AVERROR(EIO);

    version = avio_r8(avctx->pb);

    if (version == 2) {
        AVStream *astream = avformat_new_stream(avctx, NULL);
        AVStream *vstream = avformat_new_stream(avctx, NULL);

        if (!astream || !vstream)
            return AVERROR(ENOMEM);

        astream->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;
        astream->codecpar->sample_rate = avio_rl32(avctx->pb);
        astream->codecpar->channels = avio_r8(avctx->pb);
        astream->codecpar->format = avio_r8(avctx->pb);

        vstream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
        vstream->codecpar->width = avio_rl32(avctx->pb);
        vstream->codecpar->height = avio_rl32(avctx->pb);
        vstream->codecpar->format = avio_r8(avctx->pb);

        // Read metadata and frame info
        avctx->metadata = av_metadata_create();
        av_dict_set(&avctx->metadata, "title", avio_get_str(avctx->pb, 1024), 0);
        av_dict_set(&avctx->metadata, "author", avio_get_str(avctx->pb, 1024), 0);

        avctx->nb_streams = 2;
        return 0;
    } else if (version == 0) {
        int sub_version = avio_r8(avctx->pb);
        if (sub_version == 3) {
            int audio_count = avio_r8(avctx->pb);
            int video_count = avio_r8(avctx->pb);

            for (int i = 0; i < audio_count; i++) {
                AVStream *astream = avformat_new_stream(avctx, NULL);
                if (!astream)
                    return AVERROR(ENOMEM);
                astream->codecpar->codec_type = AVMEDIA_TYPE_AUDIO;
                astream->codecpar->sample_rate = avio_rl32(avctx->pb);
                astream->codecpar->channels = avio_r8(avctx->pb);
            }

            for (int i = 0; i < video_count; i++) {
                AVStream *vstream = avformat_new_stream(avctx, NULL);
                if (!vstream)
                    return AVERROR(ENOMEM);
                vstream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
                vstream->codecpar->width = avio_rl32(avctx->pb);
                vstream->codecpar->height = avio_rl32(avctx->pb);
                vstream->codecpar->format = avio_r8(avctx->pb);
            }

            avctx->metadata = av_metadata_create();
            av_dict_set(&avctx->metadata, "table_index", avio_get_str(avctx->pb, 1024), 0);

            avctx->nb_streams = audio_count + video_count;
            return 0;
        } else {
            return AVERROR_INVALIDDATA;
        }
    } else {
        // Unknown version
        av_log(avctx, AV_LOG_ERROR, "Unrecognized file format version: %d\n", version);
        return AVERROR_INVALIDDATA;
    }
}

