        vstream->codecpar->format = avio_r8(avctx->pb);
        vstream->codecpar->bit_rate = avio_rl32(avctx->pb);

        // Read metadata and frame info
        avio_skip(avctx->pb, 16);
    } else if (version == 0) {
        int next = avio_r8(avctx->pb);
        if (next == 3) {
            int num_audio_tracks = avio_r8(avctx->pb);
            int num_video_tracks = avio_r8(avctx->pb);

            for (int i = 0; i < num_audio_tracks; i++) {
                AVStream *astream = avformat_new_stream(avctx, NULL);
                astream->codecpar->sample_rate = avio_rl32(avctx->pb);
                astream->codecpar->channels = avio_r8(avctx->pb);
                avio_skip(avctx->pb, 8);
            }

            for (int i = 0; i < num_video_tracks; i++) {
                AVStream *vstream = avformat_new_stream(avctx, NULL);
                vstream->codecpar->width = avio_rl16(avctx->pb);
                vstream->codecpar->height = avio_rl16(avctx->pb);
                vstream->codecpar->format = avio_r8(avctx->pb);
                avio_skip(avctx->pb, 4);
            }
        } else {
            return AVERROR(EINVAL);
        }
    } else {
        // Request a sample for unrecognized version
        av_log(avctx, AV_LOG_ERROR, "Unsupported file version. Please provide a sample file.\n");
        return AVERROR(ENOSYS);
    }

    return 0;
}

